"""Detailed explanations with diagrams: LLD questions, part 3."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, UML, STATE, TABLE, CODE

X("taskscheduler-lld",
  P("""**What you are building.** A mini `cron`/`ScheduledExecutorService`: run a job once after a delay, or repeatedly at a fixed rate, on a pool of worker threads, with the ability to cancel. The core question is: how does one thread know **which task is due next** without checking every task every millisecond?"""),
  AN("An airport departure board sorted by time. The dispatcher only ever looks at the **top** flight; it sleeps until that flight's time, then sends it to a free gate (worker). A new flight that leaves earlier simply appears at the top. Java's `DelayQueue` is that board: a priority queue ordered by run time whose `take()` blocks until the earliest item is due."),
  UML("Class diagram", [["Scheduler"], ["DelayQueue<Task>", "Task", "ExecutorService"]],
      {"Scheduler": (["queue: DelayQueue<Task>", "workers: ExecutorService", "dispatcher: Thread", "running: volatile boolean"], ["schedule(job, delayMs): Task", "scheduleAtFixedRate(job, initial, period): Task", "shutdown()"]),
       "Task": (["id (tie-breaker)", "job: Runnable", "runAtMs, periodMs", "cancelled: volatile"], ["getDelay(unit)", "compareTo(other)", "cancel()"]),
       "DelayQueue<Task>": (["min-heap by runAtMs"], ["put(task)", "take() // blocks"]), "ExecutorService": (["N worker threads"], ["submit(job)"])},
      [["Scheduler", "DelayQueue<Task>", "comp"], ["Scheduler", "ExecutorService", "comp"], ["DelayQueue<Task>", "Task", "agg", "0..*"]],
      "`Task implements Delayed`: `getDelay` tells the queue how long until it's due; `compareTo` orders by run time, then by id so equal times stay first-come-first-served."),
  SEQ("A fixed-rate heartbeat", ["Client", "Scheduler", "DelayQueue", "Dispatcher", "Worker"],
      [["Client", "Scheduler", "scheduleAtFixedRate(hb, 0, 50ms)"], ["Scheduler", "DelayQueue", "put(Task runAt = now)"],
       ["Dispatcher", "DelayQueue", "take()", "", "Blocks (no CPU) until the head task's delay reaches 0."],
       ["DelayQueue", "Dispatcher", "Task hb", "r"], ["Dispatcher", "Worker", "submit(hb.job)", "a", "The dispatcher never runs jobs itself: a slow job would delay every other task."],
       ["Dispatcher", "DelayQueue", "put(hb, runAt += 50ms)", "", "Fixed **rate**: the next time is based on the planned time, not on when the job finished, so it doesn't drift."],
       NOTE(["Client", "Worker"], "cancel() just sets a flag; the dispatcher skips cancelled tasks when they reach the head")],
      "Real output: one-off tasks A (100 ms) and B (200 ms) ran in order, and the 50 ms heartbeat ran at least 5 times."),
  TABLE("Design choices", ["Choice", "Why", "Production version"],
        [["DelayQueue (heap)", "O(log n) insert, O(1) peek of the next task, blocking take", "timing wheel for millions of timers (Kafka, Netty)"],
         ["separate dispatcher + pool", "dispatch is fast; slow jobs only occupy a worker", "same; add per-job timeouts"],
         ["lazy cancel flag", "O(1) cancel; removing from a heap is O(n)", "same"],
         ["in-memory only", "simple", "persist jobs in a DB + leader election so they survive restarts (see the distributed job scheduler HLD)"]]))

X("kvstore-lld",
  P("""**What you are building.** A tiny Redis: `set/get/delete` with an optional **time-to-live**, plus **nested transactions** (`BEGIN … ROLLBACK/COMMIT`). Expired keys must never be returned, and it must be safe with many threads."""),
  AN("Transactions work like **undo notes**. On `BEGIN` you open a fresh notepad. The first time a key is changed inside it, you write down its *old* value. `ROLLBACK` replays the notepad to restore the old values; `COMMIT` throws the notepad away (or hands its notes to the outer transaction so that one can still be undone)."),
  UML("Class diagram", [["KvStore"], ["Entry", "Deque<Map> txUndo"]],
      {"KvStore": (["data: Map<String, Entry>", "txUndo: Deque<Map<key, Optional<Entry>>>", "clock: LongSupplier"], ["set(k, v, ttlMs)", "get(k): Optional", "delete(k)", "begin() / rollback() / commit()", "sweep(): int", "- remember(k)"]),
       "Entry": ("record", ["value", "expiresAt (0 = never)"], ["expired(now)"]), "Deque<Map> txUndo": (["one undo map per open transaction"], [])},
      [["KvStore", "Entry", "comp"], ["KvStore", "Deque<Map> txUndo", "comp", "stack"]]),
  TABLE("The real demo, line by line", ["Command", "data[a]", "undo stack (top first)", "get(a)"],
        [["set a 10", "10", "—", ""], ["BEGIN; set a 20", "20", "[{a: 10}]", ""], ["BEGIN; set a 30; delete a", "—", "[{a: 20}], [{a: 10}]", "empty"],
         ["ROLLBACK", "20", "[{a: 10}]", "**20**"], ["COMMIT", "20", "— (outer notes dropped)", "**20**"], ["set session xyz TTL 1 s; clock +1 s", "expired", "—", "empty (lazy expiry)"]],
        "`remember` uses `putIfAbsent`, so only the value **before the first change** in a transaction is recorded."),
  KEY("Two kinds of expiry, like Redis: **lazy** (check on every `get` and delete if expired, so readers never see stale data) and **active** (`sweep()` run periodically, so keys nobody reads don't leak memory). In the demo `get` already removed the expired key, so the sweep found 0 left.", "Expiry"),
  TABLE("Complexity", ["Operation", "Time"], [["get / set / delete", "O(1)"], ["begin / commit", "O(1) / O(keys changed)"], ["rollback", "O(keys changed in that transaction)"], ["sweep", "O(n), or sample random keys like Redis does"]]))

X("shoppingcart-lld",
  P("""**What you are building.** A cart that holds products with quantities and a **pricing engine** that applies a chain of discounts: 10% off a category, buy-2-get-1, and a flat coupon with a minimum order. Marketing adds new discount types every month, so the key requirement is that new rules plug in without editing existing code."""),
  AN("A checkout counter where the bill passes through a row of stamps: each stamp (discount rule) looks at the bill so far and may knock something off, writing a line on the receipt. To add a promotion you add a stamp; you never rebuild the counter."),
  UML("Class diagram", [["PricingEngine", "Cart"], ["Discount", "Line"], ["CategoryPercent", "BuyXGetY", "FlatCoupon", "Product"], ["Applied", "Category"]],
      {"PricingEngine": (["rules: List<Discount>  (order matters)"], ["price(cart, breakdown): long"]), "Cart": (["lines: LinkedHashMap<sku, Line>"], ["add(product, qty)", "remove(sku)", "subtotal()"]),
       "Discount": ("interface", [], ["apply(cart, runningTotal): Optional<Applied>"]),
       "CategoryPercent": (["category, percent"], []), "BuyXGetY": (["sku, x, y"], []), "FlatCoupon": (["code, off, minOrder"], []),
       "Line": ("record", ["product, qty"], ["total()"]), "Product": ("record", ["sku, name", "pricePaise, category"], []),
       "Applied": ("record", ["name, amountPaise"], []), "Category": ("enum", ["ELECTRONICS, FASHION,", "GROCERY"], [])},
      [["PricingEngine", "Discount", "agg", "ordered"], ["PricingEngine", "Cart", "dep", "prices"], ["Cart", "Line", "comp"], ["Line", "Product", "assoc"], ["Product", "Category", "assoc"],
       ["CategoryPercent", "Discount", "impl"], ["BuyXGetY", "Discount", "impl"], ["FlatCoupon", "Discount", "impl"], ["Discount", "Applied", "dep", "returns"]],
      "Strategy + a simple Chain: each rule gets the **running total** so later rules (the coupon's minimum order) see earlier discounts."),
  TABLE("Pricing the real cart (amounts in ₹)", ["Step", "Rule", "Discount", "Running total"],
        [["0", "subtotal: headphones 2,999 + 3 T-shirts 1,497 + 4 milk 120", "", "4,616.00"], ["1", "10% off ELECTRONICS (headphones)", "−299.90", "4,316.10"],
         ["2", "buy 2 get 1 T-shirt: 3 // 3 × 1 = 1 free", "−499.00", "3,817.10"], ["3", "SAVE200: total ≥ 3,000 ✔", "−200.00", "**3,617.10**"]]),
  KEY("Money is kept in **paise (long)**, never double. The order of rules is a business decision (percent before flat coupons is the usual policy) and is configuration, not code. Ask the interviewer whether discounts stack or only the best one applies; that's one more strategy (`BestOfDiscounts`).", "Points to raise"))

X("filesystem-lld",
  P("""**What you are building.** An in-memory file system with paths like `/home/shubham/notes.md`: `mkdir -p`, write/append and read files, `ls` with sorted names, and `du` (total size of a directory). Files and directories form a **tree**, and a directory's size is the sum of its children: that's the **Composite** pattern."""),
  AN("Folders inside folders are like boxes inside boxes. Asking a box 'how heavy are you?' makes it ask each item inside; a small box asks its items, and so on, until single items (files) answer with their own weight."),
  UML("Class diagram", [["FileSystem"], ["Node"], ["FileNode", "Dir"]],
      {"FileSystem": (["root: Dir"], ["mkdir(path)", "writeFile(path, text, append)", "read(path)", "ls(path): List<String>", "du(path): long", "- dir(parts, create): Dir"]),
       "Node": ("abstract", ["name"], ["size(): long  (abstract)"]), "FileNode": (["content: StringBuilder"], ["size() = content length"]),
       "Dir": (["children: TreeMap<name, Node>"], ["size() = Σ children.size()"])},
      [["FileSystem", "Dir", "comp", "root"], ["FileNode", "Node", "inh"], ["Dir", "Node", "inh"], ["Dir", "Node", "agg", "children"]],
      "A `TreeMap` keeps children sorted, so `ls` is already alphabetical without sorting."),
  FLOW("The tree after the real demo", [["/ (root)"], ["home"], ["shubham"], ["projects", "todo.txt (12)"], ["notes.md (21)"]],
       [["/ (root)", "home"], ["home", "shubham"], ["shubham", "projects"], ["shubham", "todo.txt (12)"], ["projects", "notes.md (21)"]],
       "`du /home` = 21 + 12 = **33** characters, computed recursively by `Dir.size()`."),
  SEQ("writeFile(\"/home/shubham/projects/notes.md\", …, append)", ["Caller", "FileSystem", "root Dir", "projects Dir", "notes.md"],
      [["Caller", "FileSystem", "writeFile(path, text, true)"], ["FileSystem", "FileSystem", "parts = [home, shubham, projects, notes.md]", "", "Split on '/', ignoring empty pieces, so '//a/' works too."],
       ["FileSystem", "root Dir", "walk home → shubham → projects", "", "`dir(parts minus last, create=false)` follows `children` one level at a time; a missing folder throws, a file in the middle of the path throws."],
       ["projects Dir", "notes.md", "get or create FileNode", ""], ["FileSystem", "notes.md", "content.append(text)", "", "append=false would clear the StringBuilder first."]]),
  TABLE("Cost", ["Operation", "Time (d = path depth, k = children)"], [["mkdir / write / read", "O(d · log k)"], ["ls", "O(k)"], ["du", "O(size of subtree); cache sizes in each Dir and update on write for O(1)"]]))

X("ridesharing-lld",
  P("""**What you are building.** The core of Uber/Ola inside one service: riders request a ride, the **nearest available** driver of the right vehicle type is matched (a driver must never get two riders at once), trips move through a strict life cycle, and the fare depends on distance, vehicle type and surge."""),
  AN("A taxi stand with a dispatcher: when you ask for a car, the dispatcher points at the closest free taxi and immediately flips its 'free' sign to 'busy' before anyone else can point at it. That flip has to be atomic, or two riders get the same car."),
  UML("Class diagram", [["RideService"], ["MatchingStrategy", "Trip", "PricingStrategy"], ["NearestAvailable", "Driver", "TripState", "DistancePricing"], ["Location", "VehicleType"]],
      {"RideService": (["drivers: Map<id,Driver>", "trips: Map<id,Trip>"], ["addDriver(d)", "request(rider, from, to, type): Trip", "start(tripId)", "complete(tripId, surge): fare"]),
       "MatchingStrategy": ("interface", [], ["match(drivers, trip): Optional<Driver>"]), "NearestAvailable": ([], ["match(...)"]),
       "PricingStrategy": ("interface", [], ["fare(trip, surge): long"]), "DistancePricing": (["rates: base + per km by type"], ["fare(...)"]),
       "Trip": (["id, rider, from, to, type", "driver", "state: TripState"], ["moveTo(next)  // validated"]),
       "Driver": (["id, type, loc: Location", "available: AtomicBoolean"], []), "TripState": ("enum", ["REQUESTED, ACCEPTED,", "IN_PROGRESS, COMPLETED,", "CANCELLED"], []),
       "Location": ("record", ["x, y"], ["dist(other)"]), "VehicleType": ("enum", ["AUTO, MINI, SEDAN"], [])},
      [["RideService", "MatchingStrategy", "assoc"], ["RideService", "PricingStrategy", "assoc"], ["RideService", "Trip", "comp"], ["RideService", "Driver", "agg"], ["NearestAvailable", "MatchingStrategy", "impl"],
       ["DistancePricing", "PricingStrategy", "impl"], ["Trip", "Driver", "assoc"], ["Trip", "TripState", "assoc"], ["Driver", "Location", "assoc"], ["Driver", "VehicleType", "assoc"]]),
  STATE("Trip life cycle (illegal moves throw)", [["REQUESTED"], ["ACCEPTED", "CANCELLED"], ["IN_PROGRESS"], ["COMPLETED"]],
        [["REQUESTED", "ACCEPTED", "driver matched"], ["REQUESTED", "CANCELLED", "no driver / rider cancels"], ["ACCEPTED", "CANCELLED", "cancel"], ["ACCEPTED", "IN_PROGRESS", "start()"], ["IN_PROGRESS", "COMPLETED", "complete()"]],
        "The allowed moves are a `Map<TripState, Set<TripState>>`; the demo's attempt COMPLETED → IN_PROGRESS is rejected."),
  SEQ("Three riders, two drivers, same moment", ["Rider R0", "Rider R1", "RideService", "NearestAvailable", "Driver D1"],
      [["Rider R0", "RideService", "request(from (1,1), MINI)"], ["RideService", "NearestAvailable", "match(drivers, trip)", "", "Sort free MINI drivers by distance to the pickup: D1 at (0,0) is 1.4 away, D2 at (5,5) is 5.7 away."],
       ["NearestAvailable", "Driver D1", "available.compareAndSet(true, false)", "", "**CAS**: only one thread can flip D1 from free to busy. If it fails, try the next nearest driver."],
       ["Rider R1", "RideService", "request(...) (concurrently)", "", "R1's CAS on D1 fails (already taken), so R1 gets D2; the third rider finds no one and the trip is CANCELLED."],
       ["RideService", "Rider R0", "Trip ACCEPTED with D1", "r"],
       NOTE(["Rider R0", "Driver D1"], "start() → IN_PROGRESS, complete(surge 1.5) → COMPLETED, driver freed"),
       ["RideService", "Rider R0", "fare = round((50 + 15 × 5 km) × 1.5) = ₹188", "r", "Distance (1,1)→(4,5) = 5; MINI = ₹50 base + ₹15/km; surge 1.5×."]]),
  KEY("Lock-free matching with `AtomicBoolean.compareAndSet` per driver avoids one global lock: riders in different areas never block each other. At city scale the same idea becomes a geo-index (geohash/H3 cells) plus a reservation with a TTL in Redis; see the Uber HLD.", "Concurrency point"))
